package com.chatfade;

import java.awt.Color;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The two symptoms reported in issue #21:
 *
 * <ol>
 *   <li>"It shows an internal string for colors" — colour markup rendered as literal text
 *       in the overlay.</li>
 *   <li>"the 'Preserve In-Game Colors' option doesn't work" — the message fell back to the
 *       flat per-type colour instead of carrying the colour the game gave it.</li>
 * </ol>
 *
 * <p>The {@code @name@} macros the report was about are expanded by
 * {@link net.runelite.api.Client#macroExpand} before anything here runs, so the inputs
 * below are in the post-expansion form the pipeline actually sees. Whether expansion itself
 * is correct is the client's responsibility, not this plugin's — that is the whole reason
 * for delegating it.
 */
public class Issue21Test
{
	private static final Color PER_TYPE_FALLBACK = new Color(100, 200, 255);

	/** Post-macroExpand forms of the messages from the report. */
	private static final String[] REPORTED_MESSAGES = {
		"<col=ff3030>You have been frozen!</col>",
		"<col=30ff30>The bush is already fruiting and won't benefit from any more pollen.</col>",
		"<col=b060ff>Your Death Charge spell will be active.</col>",
		"CA_ID:330|<col=b060ff>Sam completed a hard combat task: Mad Angel.</col>",
		"<col=ff0000>CA_ID:47|<col=ffff30>Sam completed an elite combat task.</col>",
	};

	// ── Symptom 1: no markup on screen ──────────────────────

	@Test
	public void noMarkupSurvivesToTheDisplayTextPath()
	{
		for (String raw : REPORTED_MESSAGES)
		{
			String display = ChatFadePlugin.toDisplayText(ChatFadePlugin.stripIngestPrefixes(raw));

			assertFalse("markup leaked into display text: " + display, display.contains("<col="));
			assertFalse("closing tag leaked: " + display, display.contains("</col>"));
			assertFalse("unexpanded macro leaked: " + display, display.contains("@mes_hl"));
		}
	}

	@Test
	public void noMarkupSurvivesToTheColourSpanPath()
	{
		for (String raw : REPORTED_MESSAGES)
		{
			List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
				ChatFadePlugin.stripIngestPrefixes(raw), PER_TYPE_FALLBACK);

			if (spans == null)
			{
				continue; // renders through the display-text path instead
			}

			for (ColorSpan span : spans)
			{
				assertFalse("markup leaked into a span: " + span.getText(),
					span.getText().contains("<col="));
			}
		}
	}

	@Test
	public void machineReadablePrefixesAreGoneToo()
	{
		for (String raw : REPORTED_MESSAGES)
		{
			String display = ChatFadePlugin.toDisplayText(ChatFadePlugin.stripIngestPrefixes(raw));
			assertFalse("CA_ID prefix leaked: " + display, display.contains("CA_ID"));
		}
	}

	// ── Symptom 2: colour actually comes through ────────────

	@Test
	public void colouredMessageProducesSpansInsteadOfFallingBack()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff3030>You have been frozen!</col>", PER_TYPE_FALLBACK);

		assertNotNull("coloured message must produce spans, not fall back", spans);
		assertFalse(spans.isEmpty());

		boolean anyNonFallback = spans.stream().anyMatch(s -> !s.getColor().equals(PER_TYPE_FALLBACK));
		assertTrue("at least one span must carry the message's own colour", anyNonFallback);
	}

	@Test
	public void colourIsCarriedNotJustStripped()
	{
		// Distinguishes a real fix from merely deleting the markup: the resulting colour
		// must be the one the game specified, not the per-type fallback.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=b060ff>Your Death Charge spell will be active.</col>", PER_TYPE_FALLBACK);

		assertNotNull(spans);
		assertEquals(1, spans.size());
		assertEquals("Your Death Charge spell will be active.", spans.get(0).getText());
		assertEquals(new Color(0xB060FF), spans.get(0).getColor());
	}

	@Test
	public void everyReportedMessageEitherColoursOrReadsCleanly()
	{
		for (String raw : REPORTED_MESSAGES)
		{
			String stripped = ChatFadePlugin.stripIngestPrefixes(raw);
			List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(stripped, PER_TYPE_FALLBACK);
			String display = ChatFadePlugin.toDisplayText(stripped);

			assertFalse("display text should never be empty for: " + raw, display.isEmpty());

			if (spans != null)
			{
				// Reassembling the spans must reproduce the display text exactly, so the
				// two render paths can never disagree about what the message says.
				StringBuilder joined = new StringBuilder();
				spans.forEach(s -> joined.append(s.getText()));
				assertEquals("span text and display text diverge for: " + raw,
					display, joined.toString());
			}
		}
	}

	// ── Player text is not markup ───────────────────────────

	@Test
	public void playerTypedAtTextIsUntouched()
	{
		// Previously a hand-rolled matcher could eat things like "@bob_smith@". Nothing in
		// the plugin inspects @ signs any more, so player text passes through verbatim.
		assertEquals("ping @bob@ and @bob_smith@ now",
			ChatFadePlugin.toDisplayText(
				ChatFadePlugin.stripIngestPrefixes("ping @bob@ and @bob_smith@ now")));
	}
}

package com.chatfade;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntFunction;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Inline chat icons. Emoji, clan and friends chat rank badges, ironman icons and mod crowns
 * all arrive as {@code <img=N>} indexes into one shared client array, so a single path
 * covers every one of them.
 */
public class ChatIconSpanTest
{
	private static final Color FALLBACK = new Color(100, 200, 255);

	private static final BufferedImage ICON_A = new BufferedImage(11, 11, BufferedImage.TYPE_INT_ARGB);
	private static final BufferedImage ICON_B = new BufferedImage(11, 11, BufferedImage.TYPE_INT_ARGB);

	/** Stands in for the client's mod icon array. */
	private static final IntFunction<BufferedImage> RESOLVER = index ->
	{
		switch (index)
		{
			case 1:
				return ICON_A;
			case 2:
				return ICON_B;
			default:
				return null;
		}
	};

	private static String textOf(List<ColorSpan> spans)
	{
		StringBuilder sb = new StringBuilder();
		spans.forEach(s -> sb.append(s.getText()));
		return sb.toString();
	}

	// ── Icons alone are enough to need spans ────────────────

	@Test
	public void producesSpansForAMessageWithOnlyAnIcon()
	{
		// No colour markup at all, so before icons this returned null and rendered as
		// plain text with the tag stripped.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans("hi <img=1> there", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertEquals(3, spans.size());
		assertEquals("hi ", spans.get(0).getText());
		assertTrue(spans.get(1).isIcon());
		assertSame(ICON_A, spans.get(1).getImage());
		assertEquals(" there", spans.get(2).getText());
	}

	@Test
	public void iconSpansCarryNoText()
	{
		// Reassembling spans must still yield exactly what the overlay would draw as text.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans("a<img=1>b", FALLBACK, RESOLVER);

		assertEquals("ab", textOf(spans));
	}

	@Test
	public void handlesSeveralIconsInOneMessage()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans("<img=1><img=2>go", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertEquals(3, spans.size());
		assertSame(ICON_A, spans.get(0).getImage());
		assertSame(ICON_B, spans.get(1).getImage());
		assertEquals("go", spans.get(2).getText());
	}

	@Test
	public void combinesIconsWithColourMarkup()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>red <img=1> still red</col>", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertEquals("red  still red", textOf(spans));
		assertEquals(new Color(0xFF0000), spans.get(0).getColor());
		assertTrue(spans.get(1).isIcon());
		assertEquals(new Color(0xFF0000), spans.get(2).getColor());
	}

	// ── Unresolvable and disabled ───────────────────────────

	@Test
	public void dropsIconsWhenNoResolverIsSupplied()
	{
		// The option is off: behaviour must match what it was before icons existed.
		assertNull(ChatFadePlugin.parseColorSpans("hi <img=1> there", FALLBACK, null));
	}

	@Test
	public void dropsIconsTheClientCannotResolve()
	{
		// An index past the end of the array, or a sprite that will not convert.
		assertNull(ChatFadePlugin.parseColorSpans("hi <img=99> there", FALLBACK, RESOLVER));
	}

	@Test
	public void ignoresMalformedIconTags()
	{
		assertNull(ChatFadePlugin.parseColorSpans("hi <img=> there", FALLBACK, RESOLVER));
		assertNull(ChatFadePlugin.parseColorSpans("hi <imgx=1> there", FALLBACK, RESOLVER));
	}

	// ── Independence from the colour option ─────────────────

	@Test
	public void dropSpanColoursKeepsIconsAndFlattensText()
	{
		// "Preserve In-Game Colors" off must still draw icons, with text at the per-type
		// colour rather than whatever the message asked for.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>red <img=1></col>", FALLBACK, RESOLVER);
		List<ColorSpan> flattened = ChatFadePlugin.dropSpanColours(spans, FALLBACK);

		assertNotNull(flattened);
		assertEquals("red ", flattened.get(0).getText());
		assertEquals(FALLBACK, flattened.get(0).getColor());
		assertTrue(flattened.get(1).isIcon());
	}

	@Test
	public void dropSpanColoursReturnsNullWhenThereIsNothingToDraw()
	{
		// Colour-only spans with no icons collapse back to plain text rendering.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>just red</col>", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertNull(ChatFadePlugin.dropSpanColours(spans, FALLBACK));
		assertNull(ChatFadePlugin.dropSpanColours(null, FALLBACK));
	}

	// ── Text spans are unaffected ───────────────────────────

	@Test
	public void plainTextIsStillNotWorthSpans()
	{
		assertNull(ChatFadePlugin.parseColorSpans("no markup here", FALLBACK, RESOLVER));
	}

	@Test
	public void escapedCharactersStillSurviveAlongsideIcons()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<at>bob<at> <img=1>", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertEquals("@bob@ ", textOf(spans));
		assertTrue(spans.get(spans.size() - 1).isIcon());
	}

	@Test
	public void iconSpansAreNotFilteredOutAsEmpty()
	{
		// Icon spans deliberately hold empty text; the empty-span cleanup must skip them.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans("<img=1>", FALLBACK, RESOLVER);

		assertNotNull(spans);
		assertEquals(1, spans.size());
		assertTrue(spans.get(0).isIcon());
		assertFalse(spans.isEmpty());
	}
}

package com.chatfade;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * End-to-end coverage of the text pipeline a chat message goes through on ingest:
 * prefix stripping, then reduction to display text.
 *
 * <p>Inputs are in the form the pipeline actually receives: the game's {@code @name@}
 * colour macros are expanded to {@code <col=...>} by
 * {@link net.runelite.api.Client#macroExpand} before any of this runs.
 */
public class MessageIngestTest
{
	private static String ingest(String raw)
	{
		return ChatFadePlugin.toDisplayText(ChatFadePlugin.stripIngestPrefixes(raw));
	}

	// ── Issue #21: @name@ colour tokens ─────────────────────

	@Test
	public void stripsFreezeMessageMarkup()
	{
		assertEquals("You have been frozen!",
			ingest("<col=ff3030>You have been frozen!</col>"));
	}

	@Test
	public void stripsFarmingMessageMarkup()
	{
		assertEquals("The bush is already fruiting and won't benefit from any more pollen.",
			ingest("<col=30ff30>The bush is already fruiting and won't benefit from any more pollen.</col>"));
	}

	@Test
	public void stripsNestedMarkup()
	{
		assertEquals("Congratulations, you found a rare item!",
			ingest("<col=b060ff>Congratulations, <col=ff0000>you found a rare item!</col></col>"));
	}

	// ── Existing prefix stripping must survive ──────────────

	@Test
	public void stripsCombatAchievementPrefix()
	{
		assertEquals("Sam completed a hard combat task: Mad Angel.",
			ingest("CA_ID:330|Sam completed a hard combat task: Mad Angel."));
	}

	@Test
	public void stripsCombatAchievementPrefixBehindColourTags()
	{
		assertEquals("Sam completed a hard combat task.",
			ingest("<col=ff0000>CA_ID:330|Sam completed a hard combat task."));
	}

	@Test
	public void stripsLevelUpSkillIdPrefix()
	{
		assertEquals("Check the skill guide for more information.",
			ingest("24|Check the skill guide for more information."));
	}

	@Test
	public void combinesPrefixStrippingWithMarkupStripping()
	{
		// The case issue #21 was actually reported against: a CA message that also
		// carries colour markup.
		assertEquals("Sam completed a hard combat task: Mad Angel.",
			ingest("CA_ID:330|<col=b060ff>Sam completed a hard combat task: Mad Angel.</col>"));
	}

	// ── Ordinary messages pass through unchanged ────────────

	@Test
	public void leavesPlainMessagesAlone()
	{
		assertEquals("You feel a surge of power.", ingest("You feel a surge of power."));
	}

	@Test
	public void doesNotStripPlayerAtText()
	{
		// Nothing in the plugin inspects @ signs any more, so player text is verbatim.
		assertEquals("ping @bob@ and @bob_smith@ when you're on",
			ingest("ping @bob@ and @bob_smith@ when you're on"));
	}

	@Test
	public void doesNotMistakeLeadingNumberForSkillId()
	{
		// The skill-id rule requires a trailing pipe; a message that merely starts with
		// digits must survive intact.
		assertEquals("20 Kingdom favour gained.", ingest("20 Kingdom favour gained."));
	}

	@Test
	public void handlesNullSafely()
	{
		assertEquals("", ingest(null));
	}

	// ── Escaped printable characters ────────────────────────

	@Test
	public void restoresEscapedAtSigns()
	{
		// The game escapes a typed "@" as <at>. Blind tag removal deleted it, so player
		// text lost its @ signs entirely in the overlay while the chatbox kept them.
		assertEquals("@bob@", ingest("<at>bob<at>"));
		assertEquals("@bob", ingest("<at>bob"));
		assertEquals("Whatthe@bdbd", ingest("Whatthe<at>bdbd"));
	}

	@Test
	public void restoresOtherEscapedPrintables()
	{
		assertEquals("<", ingest("<lt>"));
		assertEquals(">", ingest("<gt>"));
		assertEquals("5 < 6 and 7 > 2", ingest("5 <lt> 6 and 7 <gt> 2"));
	}

	@Test
	public void stillDropsRealMarkupAroundEscapedCharacters()
	{
		assertEquals("@bob@", ingest("<col=ff0000><at>bob<at></col>"));
	}

	@Test
	public void collapsesLineBreaksToSpaces()
	{
		// The overlay draws one line per message, so a break must not emit a control char.
		assertEquals("one two", ingest("one<br>two"));
	}

	// ── Combat Achievement markers ──────────────────────────

	@Test
	public void stripsCaIdMarkerBehindARankIcon()
	{
		// The real clan broadcast: a rank icon, a space, then the marker. The space is what
		// the original pattern did not allow, so 95% of these kept the marker on screen.
		assertEquals("TradePending has completed a master combat task: A siphon will solve this.",
			ingest("<img=2> CA_ID:413|TradePending has completed a master combat task: A siphon will solve this."));
	}

	@Test
	public void stripsCaIdMarkerWithoutAnIcon()
	{
		assertEquals("DevMoney420 has completed a master combat task: ... 'til Dawn.",
			ingest("CA_ID:96|DevMoney420 has completed a master combat task: ... 'til Dawn."));
	}

	@Test
	public void stripsCaIdMarkerBehindAColourTag()
	{
		assertEquals("Sam completed a hard combat task.",
			ingest("<col=ff0000>CA_ID:330|Sam completed a hard combat task."));
	}

	@Test
	public void keepsTheRankIconWhenStrippingTheMarker()
	{
		// The icon is part of the message, not part of the marker — it must survive so the
		// badge still renders. toDisplayText drops it here; the span path turns it into an
		// icon. What matters is that the strip does not eat it.
		assertEquals("<img=2> Bob has completed an elite combat task: Snake. Snake!?",
			ChatFadePlugin.stripIngestPrefixes(
				"<img=2> CA_ID:228|Bob has completed an elite combat task: Snake. Snake!?"));
	}

	@Test
	public void stripsSkillIdPrefixBehindAnIcon()
	{
		assertEquals("Check the skill guide for more information.",
			ingest("<img=5> 24|Check the skill guide for more information."));
	}

	@Test
	public void leavesOrdinaryPipesAlone()
	{
		// Only a leading numeric id followed by a pipe is a prefix.
		assertEquals("Bob says a|b is fine", ingest("Bob says a|b is fine"));
	}
}

package com.chatfade;

import java.awt.Color;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

/**
 * The one invariant that keeps highlighting from turning into a precedence matrix:
 * the game's colour always wins, and only text still at the fallback colour is repainted.
 */
public class HighlighterTest
{
	private static final Color FALLBACK = new Color(100, 200, 255);
	private static final Color GAME = new Color(0xFF0000);
	private static final Color TIER = new Color(0xFF66B2);

	private static String textOf(List<ColorSpan> spans)
	{
		StringBuilder sb = new StringBuilder();
		spans.forEach(s -> sb.append(s.getText()));
		return sb.toString();
	}

	// ── Uncoloured messages ─────────────────────────────────

	@Test
	public void highlightsRangeWhenThereAreNoExistingSpans()
	{
		String text = "Bob received a drop: Whip (1,000 coins).";
		int start = text.indexOf("Whip");
		int end = text.indexOf(')') + 1;

		List<ColorSpan> out = Highlighter.highlightRange(null, text, FALLBACK, start, end, TIER);

		assertNotNull(out);
		assertEquals(3, out.size());
		assertEquals("Bob received a drop: ", out.get(0).getText());
		assertEquals(FALLBACK, out.get(0).getColor());
		assertEquals("Whip (1,000 coins)", out.get(1).getText());
		assertEquals(TIER, out.get(1).getColor());
		assertEquals(".", out.get(2).getText());
		assertEquals(FALLBACK, out.get(2).getColor());
	}

	@Test
	public void reassembledTextIsUnchanged()
	{
		// The renderer draws span text verbatim, so highlighting must never alter content.
		String text = "Bob received a drop: Whip (1,000 coins).";
		List<ColorSpan> out = Highlighter.highlightRange(null, text, FALLBACK, 21, 39, TIER);

		assertEquals(text, textOf(out));
	}

	// ── The invariant ───────────────────────────────────────

	@Test
	public void neverOverridesAColourTheGameChose()
	{
		// The middle span was coloured by the game and must survive untouched, even though
		// the highlight range covers it.
		List<ColorSpan> spans = Arrays.asList(
			new ColorSpan("plain ", FALLBACK),
			new ColorSpan("GAME", GAME),
			new ColorSpan(" tail", FALLBACK));

		List<ColorSpan> out = Highlighter.highlightRange(spans, "plain GAME tail", FALLBACK,
			0, 15, TIER);

		assertEquals("plain GAME tail", textOf(out));
		ColorSpan gameSpan = out.stream().filter(s -> "GAME".equals(s.getText())).findFirst().orElse(null);
		assertNotNull("the game-coloured span should still exist", gameSpan);
		assertEquals("and keep its colour", GAME, gameSpan.getColor());
	}

	@Test
	public void recolboursOnlyTheUnclaimedPortions()
	{
		List<ColorSpan> spans = Arrays.asList(
			new ColorSpan("aaa", FALLBACK),
			new ColorSpan("bbb", GAME));

		List<ColorSpan> out = Highlighter.highlightRange(spans, "aaabbb", FALLBACK, 0, 6, TIER);

		assertEquals(TIER, out.get(0).getColor());
		assertEquals(GAME, out.get(1).getColor());
	}

	// ── No-ops ──────────────────────────────────────────────

	@Test
	public void returnsInputUnchangedWhenNothingIsRecoloured()
	{
		List<ColorSpan> spans = Arrays.asList(new ColorSpan("all game coloured", GAME));

		assertSame("should not manufacture new spans for a no-op",
			spans, Highlighter.highlightRange(spans, "all game coloured", FALLBACK, 0, 17, TIER));
	}

	@Test
	public void rejectsOutOfBoundsAndEmptyRanges()
	{
		String text = "short";

		assertSame(null, Highlighter.highlightRange(null, text, FALLBACK, -1, 3, TIER));
		assertSame(null, Highlighter.highlightRange(null, text, FALLBACK, 0, 99, TIER));
		assertSame(null, Highlighter.highlightRange(null, text, FALLBACK, 3, 3, TIER));
		assertSame(null, Highlighter.highlightRange(null, null, FALLBACK, 0, 1, TIER));
	}

	@Test
	public void handlesRangeSpanningMultipleUnclaimedSpans()
	{
		List<ColorSpan> spans = Arrays.asList(
			new ColorSpan("one ", FALLBACK),
			new ColorSpan("two ", FALLBACK),
			new ColorSpan("three", FALLBACK));

		List<ColorSpan> out = Highlighter.highlightRange(spans, "one two three", FALLBACK, 4, 8, TIER);

		assertEquals("one two three", textOf(out));
		ColorSpan highlighted = out.stream().filter(s -> TIER.equals(s.getColor())).findFirst().orElse(null);
		assertNotNull(highlighted);
		assertEquals("two ", highlighted.getText());
	}

	// ── The narrow exception for recognised drops ────────────

	@Test
	public void replaceGameColourOverridesInsideTheRangeOnly()
	{
		// The game paints its whole "Valuable drop" line one flat colour. Tiering must be
		// able to replace that within the matched item region...
		String text = "Valuable drop: Rune kiteshield (31,852 coins)";
		List<ColorSpan> spans = Arrays.asList(new ColorSpan(text, GAME));

		// Take the offsets from the parser rather than hardcoding them, so the test
		// exercises the same region the plugin actually highlights.
		LootBroadcast.Match m = LootBroadcast.parse(text);
		assertNotNull(m);

		List<ColorSpan> out = Highlighter.highlightRange(spans, text, FALLBACK,
			m.start, m.end, TIER, true);

		assertEquals(text, textOf(out));
		assertEquals("Valuable drop: ", out.get(0).getText());
		assertEquals("the prefix keeps the game's colour", GAME, out.get(0).getColor());
		assertEquals("Rune kiteshield (31,852 coins)", out.get(1).getText());
		assertEquals("the item region is tiered", TIER, out.get(1).getColor());
	}

	@Test
	public void withoutTheFlagGameColourStillWins()
	{
		// ...but the default must remain "the game's colour wins" for everything else.
		List<ColorSpan> spans = Arrays.asList(new ColorSpan("all game coloured", GAME));

		assertSame(spans,
			Highlighter.highlightRange(spans, "all game coloured", FALLBACK, 0, 17, TIER, false));
	}
}

package com.chatfade;

import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Covers issue #20. For PRIVATECHATOUT the name field holds the recipient rather than the
 * local player, so without a direction prefix both directions render identically.
 */
public class PrivateMessagePrefixTest
{
	private static String prefix(String sender, ChatMessageType type)
	{
		return ChatFadePlugin.applyPrivateMessagePrefix(sender, type, true);
	}

	@Test
	public void incomingPrivateMessageIsPrefixedFrom()
	{
		assertEquals("From Zezima", prefix("Zezima", ChatMessageType.PRIVATECHAT));
	}

	@Test
	public void outgoingPrivateMessageIsPrefixedTo()
	{
		assertEquals("To Zezima", prefix("Zezima", ChatMessageType.PRIVATECHATOUT));
	}

	@Test
	public void moderatorPrivateMessageIsPrefixedFrom()
	{
		assertEquals("From Mod Ash", prefix("Mod Ash", ChatMessageType.MODPRIVATECHAT));
	}

	@Test
	public void directionsAreDistinguishable()
