package com.chatfade;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Covers the plugin's own message filtering, added alongside issue #11. */
public class IgnoreListTest
{
	private IgnoreList list;

	@Before
	public void setUp()
	{
		list = new IgnoreList();
	}

	// ── Text fragments ──────────────────────────────────────

	@Test
	public void matchesConfiguredFragment()
	{
		list.rebuild("surge of power", "");

		assertTrue(list.matches("You feel a surge of power."));
		assertFalse(list.matches("You feel nothing at all."));
	}

	@Test
	public void fragmentMatchingIsCaseInsensitive()
	{
		list.rebuild("SURGE OF POWER", "");
		assertTrue(list.matches("You feel a surge of power."));
	}

	@Test
	public void fragmentMatchingIgnoresColourMarkup()
	{
		// A filter typed in plain text should still catch a message the game coloured.
		// Macros are already expanded to <col=...> by the time matching runs.
		list.rebuild("surge of power", "");

		assertTrue(list.matches("<col=ff0000>You feel a surge of power.</col>"));
		assertTrue(list.matches("<col=ff3030>You feel a <col=00ff00>surge of power</col>.</col>"));
	}

	@Test
	public void splitsFragmentsOnCommas()
	{
		list.rebuild("one thing, another thing ,third", "");

		assertEquals(3, list.fragmentCount());
		assertTrue(list.matches("here is another thing for you"));
		assertTrue(list.matches("the third option"));
	}

	// ── Regular expressions ─────────────────────────────────

	@Test
	public void matchesConfiguredRegex()
	{
		list.rebuild("", "^you have \\d+ charges?");

		assertTrue(list.matches("You have 12 charges"));
		assertFalse(list.matches("You have many charges"));
	}

	@Test
	public void supportsMultipleRegexLines()
	{
		list.rebuild("", "^first\n^second");

		assertEquals(2, list.patternCount());
		assertTrue(list.matches("first message"));
		assertTrue(list.matches("second message"));
		assertFalse(list.matches("third message"));
	}

	@Test
	public void skipsInvalidRegexWithoutBreakingTheRest()
	{
		list.rebuild("", "[unclosed\n^valid");

		assertEquals("the bad pattern should be dropped, not kept", 1, list.patternCount());
		assertTrue("the good pattern must still apply", list.matches("valid message"));
	}

	@Test
	public void invalidRegexAloneDisablesNothingElse()
	{
		list.rebuild("keepme", "[unclosed");

		assertEquals(0, list.patternCount());
		assertTrue("fragments must still work", list.matches("please keepme here"));
	}

	// ── Empty and edge states ───────────────────────────────

	@Test
	public void emptyConfigMatchesNothing()
	{
		list.rebuild("", "");

		assertFalse(list.matches("any message at all"));
		assertEquals(0, list.fragmentCount());
		assertEquals(0, list.patternCount());
	}

	@Test
	public void handlesNullConfigValues()
	{
		list.rebuild(null, null);
		assertFalse(list.matches("any message at all"));
	}

	@Test
	public void blankAndWhitespaceEntriesAreDiscarded()
	{
		list.rebuild(" , ,  ", "\n\n   \n");

		assertEquals(0, list.fragmentCount());
		assertEquals(0, list.patternCount());
		assertFalse("an all-blank config must not swallow every message", list.matches("hello"));
	}

	@Test
	public void rebuildReplacesRatherThanAccumulates()
	{
		list.rebuild("first", "");
		list.rebuild("second", "");

		assertEquals(1, list.fragmentCount());
		assertFalse(list.matches("first message"));
		assertTrue(list.matches("second message"));
	}
}

package com.chatfade;

import java.awt.Color;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Structural checks on the config panel and the built-in colour palette.
 *
 * <p>The position test exists because PR #19 left two Message Types items sharing
 * position 37, which makes their order in the panel arbitrary — a class of bug that is
 * invisible in review but trivial to catch here.
 */
public class ChatFadeConfigTest
{
	/** @return every {@code @ConfigItem}, grouped by the section it belongs to */
	private static Map<String, List<Method>> itemsBySection()
	{
		Map<String, List<Method>> bySection = new HashMap<>();
		for (Method method : ChatFadeConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			bySection.computeIfAbsent(item.section(), k -> new ArrayList<>()).add(method);
		}
		return bySection;
	}

	@Test
	public void noTwoItemsInASectionShareAPosition()
	{
		List<String> clashes = new ArrayList<>();

		for (Map.Entry<String, List<Method>> section : itemsBySection().entrySet())
		{
			Map<Integer, String> seen = new HashMap<>();
			for (Method method : section.getValue())
			{
				ConfigItem item = method.getAnnotation(ConfigItem.class);
				String previous = seen.put(item.position(), item.keyName());
				if (previous != null)
				{
					clashes.add(String.format("section '%s' position %d: %s and %s",
						section.getKey(), item.position(), previous, item.keyName()));
				}
			}
		}

		if (!clashes.isEmpty())
		{
			fail("config items share a position, so their panel order is arbitrary:\n  "
				+ String.join("\n  ", clashes));
		}
	}

	@Test
	public void everyConfigItemHasAKeyNameAndDescription()
	{
		for (List<Method> methods : itemsBySection().values())
		{
			for (Method method : methods)
			{
				ConfigItem item = method.getAnnotation(ConfigItem.class);
				assertTrue("missing keyName on " + method.getName(), !item.keyName().isEmpty());
				assertTrue("missing name on " + method.getName(), !item.name().isEmpty());
				assertTrue("missing description on " + method.getName(), !item.description().isEmpty());
			}
		}
	}

	@Test
	public void configKeyNamesAreUnique()
	{
		Set<String> seen = new HashSet<>();
		for (List<Method> methods : itemsBySection().values())
		{
			for (Method method : methods)
			{
				String key = method.getAnnotation(ConfigItem.class).keyName();
				assertTrue("duplicate config keyName: " + key, seen.add(key));
			}
		}
	}

	@Test
	public void newClanTogglesExistAndDefaultToVisible()
	{
		// PR #19 added these; defaulting them to true keeps upgrade behaviour unchanged.
		assertTrue(new ChatFadeConfig() {}.showClanChat());
		assertTrue(new ChatFadeConfig() {}.showGuestClanChat());
		assertTrue(new ChatFadeConfig() {}.showGIMChat());
	}

	@Test
	public void pmDirectionDefaultsOn()
	{
		assertTrue(new ChatFadeConfig() {}.showPmDirection());
	}

	// ── Built-in palette (issue #19) ────────────────────────

	@Test
	public void clanVariantsHaveDistinctBuiltInColours()
	{
		Color clan = ChatFadePlugin.getColorForType(ChatMessageType.CLAN_CHAT);
		Color guest = ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GUEST_CHAT);
		Color gim = ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GIM_CHAT);

		assertNotEquals("clan and guest clan must be distinguishable", clan, guest);
		assertNotEquals("clan and GIM must be distinguishable", clan, gim);
		assertNotEquals("guest clan and GIM must be distinguishable", guest, gim);
	}

	@Test
	public void clanBroadcastsMatchTheirChatColour()
	{
		// The *_MESSAGE variants are the system lines for each channel and should track
		// the colour of the channel they belong to.
		assertEquals(ChatFadePlugin.getColorForType(ChatMessageType.CLAN_CHAT),
			ChatFadePlugin.getColorForType(ChatMessageType.CLAN_MESSAGE));
		assertEquals(ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GUEST_CHAT),
			ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GUEST_MESSAGE));
		assertEquals(ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GIM_CHAT),
			ChatFadePlugin.getColorForType(ChatMessageType.CLAN_GIM_MESSAGE));
	}

	@Test
	public void everyMessageTypeResolvesToANonNullColour()
	{
		for (ChatMessageType type : ChatMessageType.values())
		{
			org.junit.Assert.assertNotNull("no colour for " + type,
				ChatFadePlugin.getColorForType(type));
		}
	}
}

package com.chatfade;

import java.awt.Color;
import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Covers removal of messages blocked by RuneLite's Chat Filter plugin.
 *
 * <p>The regression this guards against: matching blocked messages by text meant that with
 * the Chat Filter plugin's "Collapse game chat" / "Collapse player chat" options enabled —
 * where every duplicate is reported as blocked — the still-visible first copy was deleted
 * along with the duplicate.
 */
public class ChatFilterRemovalTest
{
	private ChatFadePlugin plugin;

	@Before
	public void setUp()
	{
		// The message list is initialised inline, so no injection is needed to exercise
		// removal on its own.
		plugin = new ChatFadePlugin();
	}

	private void add(int messageId, String text)
	{
		add(messageId, text, text);
	}

	private void add(int messageId, String text, String rawText)
	{
		plugin.getMessages().add(FadingMessage.builder()
			.text(text)
			.rawText(rawText)
			.type(ChatMessageType.GAMEMESSAGE)
			.timestamp(System.currentTimeMillis())
			.color(Color.WHITE)
			.messageId(messageId)
			.build());
	}

	private List<FadingMessage> remaining()
	{
		return plugin.getMessages();
	}

	@Test
	public void removesTheBlockedMessage()
	{
		add(1, "buying gf 1m");
		add(2, "You feel a surge of power.");

		plugin.removeBlockedMessage(1);

		assertEquals(1, remaining().size());
		assertEquals("You feel a surge of power.", remaining().get(0).getText());
	}

	@Test
	public void keepsEarlierDuplicateWhenACollapsedCopyIsBlocked()
	{
		// The collapse regression, stated directly: two messages with identical text but
		// distinct ids. Blocking the second must not take the first with it.
		add(10, "You have killed a Mad Angel.");
		add(11, "You have killed a Mad Angel.");

		plugin.removeBlockedMessage(11);

		assertEquals(1, remaining().size());
		assertEquals(10, remaining().get(0).getMessageId());
	}

	@Test
	public void keepsEarlierDuplicatesAcrossARunOfCollapsedMessages()
	{
		add(10, "You have killed a Mad Angel.");
		for (int id = 11; id <= 14; id++)
		{
			add(id, "You have killed a Mad Angel.");
			plugin.removeBlockedMessage(id);
		}

		assertEquals("only the first copy should survive a collapsed run", 1, remaining().size());
		assertEquals(10, remaining().get(0).getMessageId());
	}

	@Test
	public void ignoresReplayedMessagesWithNoStableId()
	{
		add(1, "buying gf 1m");
		add(-1, "replayed public chat");

		plugin.removeBlockedMessage(-1);

		assertEquals("a -1 id must not match anything", 2, remaining().size());
	}

	@Test
	public void unknownIdRemovesNothing()
	{
		add(1, "one");
		add(2, "two");

		plugin.removeBlockedMessage(99);

		assertEquals(2, remaining().size());
	}

	@Test
	public void identicalTextIsNotSufficientToRemove()
	{
		add(5, "Your Death Charge spell will be active.");
		add(6, "Your Death Charge spell will be active.");
		add(7, "Your Death Charge spell will be active.");

		plugin.removeBlockedMessage(6);

		assertEquals(2, remaining().size());
		assertTrue(remaining().stream().anyMatch(m -> m.getMessageId() == 5));
		assertTrue(remaining().stream().anyMatch(m -> m.getMessageId() == 7));
	}

	// ── The chatbox rebuild must not clobber other plugins ──

	@Test
	public void leavesTheMessageAloneWhenTheFilterChangedNothing()
	{
		// Regression: the chatbox rebuild hands us the game's original text for every line
		// it redraws. Adopting it unconditionally reverted RuneLite's chat-command rewrite,
		// so "!kc vard" briefly showed the real kill count and then snapped back to the
		// raw command.
		add(1, "Vardorvis kill count: 850", "!Kc vard");

		plugin.applyFilteredText(1, "!Kc vard");

		assertEquals("the resolved command output must survive",
			"Vardorvis kill count: 850", remaining().get(0).getText());
	}

	@Test
	public void keepsTheMessageNodeWhenNothingWasFiltered()
	{
		// Releasing the node would stop any later rewrite from ever being picked up.
		add(2, "!Kc vard", "!Kc vard");
		FadingMessage msg = remaining().get(0);

		plugin.applyFilteredText(2, "!Kc vard");

		assertEquals("!Kc vard", msg.getText());
	}

	@Test
	public void ignoresAnUnknownMessageId()
	{
		add(1, "hello", "hello");

		plugin.applyFilteredText(99, "something else");

		assertEquals("hello", remaining().get(0).getText());
	}
}

package com.chatfade;

import java.awt.Color;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Covers {@link ChatFadePlugin#parseColorSpans}, which backs the "Preserve In-Game Colors"
 * option. Issue #21: messages coloured purely with {@code @name@} tokens carry no
 * {@code <col=...>} tag, so the parser used to bail out and fall back to the flat per-type
 * colour.
 */
public class ColorSpanParsingTest
{
	private static final Color FALLBACK = new Color(100, 200, 255);

	// ── Expanded macros arrive as ordinary col tags ─────────

	@Test
	public void parsesExpandedMacroAsColour()
	{
		// What Client.macroExpand turns "@mes_hl_red@You have been frozen!</col>" into.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff3030>You have been frozen!</col>", FALLBACK);

		assertNotNull("coloured message should produce spans", spans);
		assertEquals(1, spans.size());
		assertEquals("You have been frozen!", spans.get(0).getText());
		assertEquals(new Color(0xFF3030), spans.get(0).getColor());
	}

	@Test
	public void closingTagRestoresFallback()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>warning</col> and the rest", FALLBACK);

		assertNotNull(spans);
		assertEquals(2, spans.size());
		assertEquals("warning", spans.get(0).getText());
		assertEquals(new Color(0xFF0000), spans.get(0).getColor());
		assertEquals(" and the rest", spans.get(1).getText());
		assertEquals(FALLBACK, spans.get(1).getColor());
	}

	// ── Existing <col=...> behaviour must be preserved ──────

	@Test
	public void stillParsesAngleBracketTags()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"a<col=ff0000>b</col>c", FALLBACK);

		assertNotNull(spans);
		assertEquals(3, spans.size());
		assertEquals("a", spans.get(0).getText());
		assertEquals(FALLBACK, spans.get(0).getColor());
		assertEquals("b", spans.get(1).getText());
		assertEquals(new Color(0xFF0000), spans.get(1).getColor());
		assertEquals("c", spans.get(2).getText());
		assertEquals(FALLBACK, spans.get(2).getColor());
	}

	@Test
	public void skipsNonColourTags()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=00ff00>hi<img=5> there", FALLBACK);

		assertNotNull(spans);
		assertEquals(1, spans.size());
		assertEquals("hi there", spans.get(0).getText());
	}

	@Test
	public void returnsNullWhenNoColourPresent()
	{
		assertNull(ChatFadePlugin.parseColorSpans("just a plain message", FALLBACK));
	}

	@Test
	public void returnsNullWhenEverythingIsFallbackColoured()
	{
		// A message whose only tag re-states the fallback is not worth span rendering.
		String sameAsFallback = String.format("<col=%06x>text</col>", FALLBACK.getRGB() & 0xFFFFFF);
		assertNull(ChatFadePlugin.parseColorSpans(sameAsFallback, FALLBACK));
	}

	// ── Player text must not be mistaken for markup ─────────

	@Test
	public void doesNotTreatPlayerAtTextAsColour()
	{
		assertNull(ChatFadePlugin.parseColorSpans("@bob@ what's up", FALLBACK));
		assertNull(ChatFadePlugin.parseColorSpans("@bob_smith@ what's up", FALLBACK));
	}

	@Test
	public void keepsPlayerAtTextInsideAColouredMessage()
	{
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>ping @bob@ and @bob_smith@ now</col>", FALLBACK);

		assertNotNull(spans);
		assertEquals(1, spans.size());
		assertEquals("ping @bob@ and @bob_smith@ now", spans.get(0).getText());
	}

	@Test
	public void keepsEscapedPrintablesInsideColouredSpans()
	{
		// The span path must restore <at> too, or a coloured message loses its @ signs
		// even though the plain-text path keeps them.
		List<ColorSpan> spans = ChatFadePlugin.parseColorSpans(
			"<col=ff0000>ping <at>bob<at> now</col>", FALLBACK);

		assertNotNull(spans);
		assertEquals(1, spans.size());
		assertEquals("ping @bob@ now", spans.get(0).getText());
	}
}

package com.chatfade;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Every sample here is a real broadcast taken from recorded clan logs (player names
 * replaced), so the parser is checked against the format the game actually sends rather
 * than an assumed one.
 */
public class LootBroadcastTest
{
	private static LootBroadcast.Match parse(String s)
	{
		return LootBroadcast.parse(s);
	}

	/** Convenience: the exact substring the parser would recolour. */
	private static String region(String message)
	{
		LootBroadcast.Match m = parse(message);
		return m == null ? null : message.substring(m.start, m.end);
	}

	// ── The two real shapes ─────────────────────────────────

	@Test
	public void parsesDropWithoutQuantity()
	{
		LootBroadcast.Match m = parse("Bob received a drop: Awakener's orb (877,401 coins).");

		assertNotNull(m);
		assertEquals(877401L, m.value);
		assertEquals("Awakener's orb (877,401 coins)",
			"Bob received a drop: Awakener's orb (877,401 coins).".substring(m.start, m.end));
	}

	@Test
	public void parsesDropWithQuantity()
	{
		LootBroadcast.Match m = parse("Bob received a drop: 18 x Runite ore (196,200 coins).");

		assertNotNull(m);
		assertEquals(196200L, m.value);
		assertEquals("18 x Runite ore (196,200 coins)",
			"Bob received a drop: 18 x Runite ore (196,200 coins).".substring(m.start, m.end));
	}

	@Test
	public void parsesDropWithCommaSeparatedQuantityAndSource()
	{
		LootBroadcast.Match m = parse("Bob received a drop: 1,000 x Soul rune (177,000 coins) from Yama.");

		assertNotNull(m);
		assertEquals(177000L, m.value);
		assertEquals("1,000 x Soul rune (177,000 coins)",
			"Bob received a drop: 1,000 x Soul rune (177,000 coins) from Yama.".substring(m.start, m.end));
	}

	@Test
	public void handlesLargeValues()
	{
		// Above 2^24, where a float-based parse would start losing precision.
		LootBroadcast.Match m = parse("Bob received a drop: Virtus robe top (61,058,904 coins).");

		assertNotNull(m);
		assertEquals(61058904L, m.value);
	}

	@Test
	public void handlesRankIconPrefixOnceMarkupIsStripped()
	{
		// The raw message begins with an <img=22> rank icon, which is already removed by
		// the time the parser sees the text.
		assertEquals("Awakener's orb (877,401 coins)",
			region("Bob received a drop: Awakener's orb (877,401 coins)."));
	}

	@Test
	public void handlesApostrophesAndHyphensInNames()
	{
		assertEquals("Ahrim's robeskirt (2,795,497 coins)",
			region("Bob received a drop: Ahrim's robeskirt (2,795,497 coins)."));
	}

	// ── Region boundaries ───────────────────────────────────

	@Test
	public void regionStartsAtTheItemNotThePlayerName()
	{
		String msg = "Bob received a drop: Abyssal whip (1,219,310 coins).";
		LootBroadcast.Match m = parse(msg);

		assertNotNull(m);
		assertEquals("Bob received a drop: ", msg.substring(0, m.start));
	}

	@Test
	public void regionExcludesTheSourceSuffix()
	{
		String msg = "Bob received a drop: 10 x Magic seed (1,031,540 coins) from Hespori.";
		LootBroadcast.Match m = parse(msg);

		assertNotNull(m);
		assertEquals(" from Hespori.", msg.substring(m.end));
	}

	// ── Non-matches ─────────────────────────────────────────

	@Test
	public void ignoresOtherClanBroadcasts()
	{
		// By far the most common clan broadcast in practice; no item, nothing to tier.
		assertNull(parse("Bob has reached Thieving level 99."));
		assertNull(parse("Bob has reached 50,000,000 XP in Magic."));
		assertNull(parse("Bob has reached combat level 126."));
	}

	@Test
	public void ignoresOrdinaryMessages()
	{
		assertNull(parse("You feel a surge of power."));
		assertNull(parse("How much for the whip?"));
		assertNull(parse(""));
		assertNull(parse(null));
	}

	@Test
	public void ignoresDropTextWithoutAValue()
	{
		// Defensive: if the format ever loses its value, do nothing rather than guess.
		assertNull(parse("Bob received a drop: Awakener's orb."));
	}

	// ── Collection log broadcasts ───────────────────────────

	@Test
	public void parsesCollectionLogItem()
	{
		String msg = "Bob received a new collection log item: Dragon defender (33/1717).";
		LootBroadcast.Match m = LootBroadcast.parseCollectionLog(msg);

		assertNotNull(m);
		assertEquals("Dragon defender", msg.substring(m.start, m.end));
	}

	@Test
	public void collectionLogNameKeepsItsOwnParentheses()
	{
		// "(g)" is part of the name; only the digits/digits counter ends it.
		String msg = "Bob received a new collection log item: Adamant full helm (g) (12/1717).";
		LootBroadcast.Match m = LootBroadcast.parseCollectionLog(msg);

		assertNotNull(m);
		assertEquals("Adamant full helm (g)", msg.substring(m.start, m.end));
	}

	@Test
	public void collectionLogExcludesTheProgressCounter()
	{
		String msg = "Bob received a new collection log item: Abyssal whip (1/1717).";
		LootBroadcast.Match m = LootBroadcast.parseCollectionLog(msg);

		assertNotNull(m);
		assertEquals(" (1/1717).", msg.substring(m.end));
	}

	@Test
	public void dropAndCollectionLogDoNotMatchEachOther()
	{
		// A collection log line has no "(N coins)" and a drop has no "(N/N)" counter.
		assertNull(LootBroadcast.parse("Bob received a new collection log item: Dragon defender (33/1717)."));
		assertNull(LootBroadcast.parseCollectionLog("Bob received a drop: Dragon defender (240,000 coins)."));
	}

	// ── The player's own "Valuable drop" notification ────────

	@Test
	public void parsesValuableDropNotification()
	{
		String msg = "Valuable drop: Rune kiteshield (31,852 coins)";
		LootBroadcast.Match m = LootBroadcast.parse(msg);

		assertNotNull(m);
		assertEquals(31852L, m.value);
		assertEquals("Rune kiteshield (31,852 coins)", msg.substring(m.start, m.end));
	}

	@Test
	public void parsesValuableDropWithQuantity()
	{
		String msg = "Valuable drop: 100 x Blood rune (34,500 coins)";
		LootBroadcast.Match m = LootBroadcast.parse(msg);

		assertNotNull(m);
		assertEquals(34500L, m.value);
		assertEquals("100 x Blood rune (34,500 coins)", msg.substring(m.start, m.end));
	}

	@Test
	public void valuableDropRegionExcludesThePrefix()
	{
		String msg = "Valuable drop: Rune kiteshield (31,852 coins)";
		LootBroadcast.Match m = LootBroadcast.parse(msg);

		assertNotNull(m);
		assertEquals("Valuable drop: ", msg.substring(0, m.start));
	}

	@Test
	public void ignoresUntradeableDropWhichCarriesNoValue()
	{
		assertNull(LootBroadcast.parse("Untradeable drop: Dark totem base"));
	}
