package com.chatfade;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Wrapping is pure given a FontMetrics, so it is exercised directly with real metrics from
 * a headless image rather than through the overlay.
 */
public class WrapPiecesTest
{
	private static FontMetrics fm;

	@BeforeClass
	public static void setUp()
	{
		Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		fm = g.getFontMetrics();
	}

	private static List<List<ColorSpan>> wrap(List<ColorSpan> pieces, int first, int cont)
	{
		return ChatFadeOverlay.wrapPieces(pieces, fm, first, cont);
	}

	private static String textOf(List<ColorSpan> line)
	{
		StringBuilder sb = new StringBuilder();
		line.forEach(p -> sb.append(p.getText()));
		return sb.toString();
	}

	private static List<ColorSpan> text(String s)
	{
		return new ArrayList<>(Arrays.asList(new ColorSpan(s, Color.WHITE)));
	}

	@Test
	public void keepsAShortMessageOnOneLine()
	{
		List<List<ColorSpan>> lines = wrap(text("short message"), 1000, 1000);

		assertEquals(1, lines.size());
		assertEquals("short message", textOf(lines.get(0)));
	}

	@Test
	public void breaksAtSpacesNotMidWord()
	{
		int width = fm.stringWidth("hello world");
		List<List<ColorSpan>> lines = wrap(text("hello world again"), width, width);

		assertTrue(lines.size() >= 2);
		for (List<ColorSpan> line : lines)
		{
			String t = textOf(line);
			assertFalse("a line should not start with a space: [" + t + "]", t.startsWith(" "));
		}
	}

	@Test
	public void losesNoTextWhenWrapping()
	{
		String source = "the quick brown fox jumps over the lazy dog";
		List<List<ColorSpan>> lines = wrap(text(source), fm.stringWidth("the quick"), fm.stringWidth("the quick"));

		StringBuilder rejoined = new StringBuilder();
		for (int i = 0; i < lines.size(); i++)
		{
			if (i > 0)
			{
				rejoined.append(' ');
			}
			rejoined.append(textOf(lines.get(i)));
		}
		assertEquals(source, rejoined.toString());
	}

	@Test
	public void breaksAWordTooLongForOneLine()
	{
		// Must terminate rather than loop forever on a word wider than the limit.
		String longWord = "supercalifragilisticexpialidocious";
		List<List<ColorSpan>> lines = wrap(text(longWord), fm.stringWidth("short"), fm.stringWidth("short"));

		assertTrue("expected the word to be split", lines.size() > 1);
		StringBuilder rejoined = new StringBuilder();
		lines.forEach(l -> rejoined.append(textOf(l)));
		assertEquals(longWord, rejoined.toString());
	}

	@Test
	public void usesTheNarrowerWidthForContinuationLines()
	{
		String source = "aaa bbb ccc ddd eee fff";
		int wide = fm.stringWidth("aaa bbb ccc ddd eee fff");

		// First line fits everything; continuation width is irrelevant.
		assertEquals(1, wrap(text(source), wide, 10).size());

		// A narrow first line forces continuation lines, which are narrower still.
		List<List<ColorSpan>> lines = wrap(text(source), fm.stringWidth("aaa bbb"), fm.stringWidth("aaa"));
		assertTrue(lines.size() >= 3);
	}

	@Test
	public void treatsAnIconAsAnUnbreakableUnit()
	{
		BufferedImage icon = new BufferedImage(11, 11, BufferedImage.TYPE_INT_ARGB);
		List<ColorSpan> pieces = new ArrayList<>();
		pieces.add(new ColorSpan("name: ", Color.WHITE));
		pieces.add(ColorSpan.icon(icon));
		pieces.add(new ColorSpan("after", Color.WHITE));

		List<List<ColorSpan>> lines = wrap(pieces, 1000, 1000);

		assertEquals(1, lines.size());
		long icons = lines.get(0).stream().filter(ColorSpan::isIcon).count();
		assertEquals("the icon must survive wrapping", 1, icons);
	}

	@Test
	public void alwaysReturnsAtLeastOneLine()
	{
		assertEquals(1, wrap(new ArrayList<>(), 100, 100).size());
		assertEquals(1, wrap(text(""), 100, 100).size());
	}
}

package com.chatfade;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the clan loot broadcast the game sends when a member receives a drop.
 *
 * <p>The game supplies the value itself, so no price lookup is needed — which also means
 * untradeable drops tier correctly and there is no dependency on the item price index
 * having loaded.
 *
 * <p>Two shapes occur, with an optional source suffix:
 * <pre>
 *   Bob received a drop: Awakener's orb (877,401 coins).
 *   Bob received a drop: 18 x Runite ore (196,200 coins).
 *   Bob received a drop: 1,000 x Soul rune (177,000 coins) from Yama.
 * </pre>
 */
final class LootBroadcast
{
	/**
	 * The item portion runs from the quantity (when present) to the closing parenthesis of
	 * the value, so the whole "what dropped and what it's worth" phrase is highlighted as
	 * one unit. Reluctant matching on the name stops it swallowing a later parenthesis.
	 */
	private static final Pattern DROP = Pattern.compile(
		"(?:received a drop|Valuable drop): (?<item>(?:[\\d,]+ x )?.+? \\((?<value>[\\d,]+) coins\\))");

	/**
	 * Collection log broadcasts carry no value, so only the item name is matched — the
	 * "(33/1717)" progress counter is left in the base colour.
	 *
	 * <p>Reluctant matching again matters here: names such as "Adamant full helm (g)"
	 * contain their own parentheses, and only the digits/digits group ends the name.
	 */
	private static final Pattern COLLECTION_LOG = Pattern.compile(
		"received a new collection log item: (?<item>.+?) \\(\\d+/\\d+\\)");

	private LootBroadcast()
	{
	}

	/**
	 * @param plainText message with all markup already removed
	 * @return the item name's region, or null when the message is not a collection log entry
	 */
	static Match parseCollectionLog(String plainText)
	{
		if (plainText == null || plainText.isEmpty())
		{
			return null;
		}

		Matcher matcher = COLLECTION_LOG.matcher(plainText);
		if (!matcher.find())
		{
			return null;
		}

		return new Match(matcher.start("item"), matcher.end("item"), 0L);
	}

	/**
	 * @param plainText message with all markup already removed
	 * @return the matched region and its value, or null when the message is not a drop
	 */
	static Match parse(String plainText)
	{
		if (plainText == null || plainText.isEmpty())
		{
			return null;
		}

		Matcher matcher = DROP.matcher(plainText);
		if (!matcher.find())
		{
			return null;
		}

		// The value group is constrained to digits and commas by the pattern, so this
		// cannot overflow into a parse failure for any string the game actually sends.
		long value;
		try
		{
			value = Long.parseLong(matcher.group("value").replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}

		return new Match(matcher.start("item"), matcher.end("item"), value);
	}

	/** A highlightable region of a message, in plain-text character offsets. */
	static final class Match
	{
		final int start;
		final int end;
		final long value;

		Match(int start, int end, long value)
		{
			this.start = start;
			this.end = end;
			this.value = value;
		}
	}
}

package com.chatfade;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Applies highlight colours to a message without ever overriding a colour the game chose.
 *
 * <p>The rule is deliberately singular: <b>the game's colour always wins, and we only paint
 * text the game left uncoloured.</b> A span still carrying the per-type fallback colour is
 * "unclaimed" and may be recoloured; anything the game explicitly coloured is left alone.
 * That keeps the interaction with "Preserve In-Game Colors" free of special cases — with it
 * off, everything is unclaimed, so highlighting simply applies throughout.
 */
final class Highlighter
{
	private Highlighter()
	{
	}

	/**
	 * Recolours the plain-text range {@code [start, end)} of a message.
	 *
	 * @param spans    existing spans, or null when the message has no game colouring
	 * @param plainText the message as displayed, which the spans concatenate to
	 * @param fallback the per-type colour, i.e. the marker for unclaimed text
	 * @param start    inclusive start offset in {@code plainText}
	 * @param end      exclusive end offset in {@code plainText}
	 * @param highlight colour to apply
	 * @return new spans, or null when nothing was recoloured and there was no prior colouring
	 */
	static List<ColorSpan> highlightRange(List<ColorSpan> spans, String plainText, Color fallback,
		int start, int end, Color highlight)
	{
		return highlightRange(spans, plainText, fallback, start, end, highlight, false);
	}

	/**
	 * As above, but {@code replaceGameColour} lifts the "game colour wins" rule for this range.
	 *
	 * <p>Used only for messages recognised as drops. The game paints its own "Valuable drop"
	 * notification a single flat colour whatever the item is worth, so a value tier says the
	 * same thing with more precision — and without this the feature could never colour the
	 * player's own drops, only other people's broadcasts. The rule still holds everywhere
	 * else: nothing outside a recognised drop overrides a colour the game chose.
	 */
	static List<ColorSpan> highlightRange(List<ColorSpan> spans, String plainText, Color fallback,
		int start, int end, Color highlight, boolean replaceGameColour)
	{
		if (plainText == null || start < 0 || end > plainText.length() || start >= end)
		{
			return spans;
		}

		List<ColorSpan> source = spans != null && !spans.isEmpty()
			? spans
			: Collections.singletonList(new ColorSpan(plainText, fallback));

		List<ColorSpan> out = new ArrayList<>(source.size() + 2);
		int offset = 0;
		boolean changed = false;

		for (ColorSpan span : source)
		{
			String text = span.getText();
			int spanStart = offset;
			int spanEnd = offset + text.length();
			offset = spanEnd;

			// Leave anything outside the range untouched, and — unless this is a recognised
			// drop — anything the game coloured.
			boolean claimedByGame = !fallback.equals(span.getColor());
			if ((claimedByGame && !replaceGameColour) || spanEnd <= start || spanStart >= end)
			{
				out.add(span);
				continue;
			}

			int localStart = Math.max(start, spanStart) - spanStart;
			int localEnd = Math.min(end, spanEnd) - spanStart;

			if (localStart > 0)
			{
				out.add(new ColorSpan(text.substring(0, localStart), span.getColor()));
			}
			out.add(new ColorSpan(text.substring(localStart, localEnd), highlight));
			if (localEnd < text.length())
			{
				out.add(new ColorSpan(text.substring(localEnd), span.getColor()));
			}
			changed = true;
		}

		if (!changed)
		{
			// Nothing was recoloured, so don't manufacture spans the renderer doesn't need.
			return spans;
		}

		return out;
	}
}

package com.chatfade;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;

/**
 * Resolves the {@code <img=N>} references the game puts in chat text into drawable images.
 *
 * <p>Everything that appears as an inline chat icon — emoji registered by RuneLite's Emoji
 * plugin, clan and friends chat rank badges, mod crowns, ironman icons — is an index into
 * the single {@link Client#getModIcons()} array, so one lookup covers all of them.
 *
 * <p>Resolution happens at message ingest, which runs on the client thread. That keeps the
 * sprite array off the render path entirely and means each icon is converted once rather
 * than every frame while the message fades.
 */
class ChatIcons
{
	static final Pattern IMG_TAG = Pattern.compile("<img=(\\d+)>");

	/**
	 * Converted sprites, keyed by mod icon index. The array is rebuilt when plugins register
	 * icons, so entries are dropped whenever its length changes rather than kept forever.
	 */
	private final Map<Integer, BufferedImage> cache = new HashMap<>();
	private int cachedIconCount = -1;

	/**
	 * @param client the client, which must be accessed from the client thread
	 * @param index the {@code N} from an {@code <img=N>} tag
	 * @return the icon, or null when the index is out of range or the sprite is unusable
	 */
	BufferedImage resolve(Client client, int index)
	{
		if (client == null || index < 0)
		{
			return null;
		}

		IndexedSprite[] icons = client.getModIcons();
		if (icons == null || index >= icons.length)
		{
			return null;
		}

		if (icons.length != cachedIconCount)
		{
			// Another plugin registered icons and the array was reallocated; indices may
			// have shifted, so previously converted entries can no longer be trusted.
			cache.clear();
			cachedIconCount = icons.length;
		}

		BufferedImage cached = cache.get(index);
		if (cached != null)
		{
			return cached;
		}

		BufferedImage converted = toBufferedImage(icons[index]);
		if (converted != null)
		{
			cache.put(index, converted);
		}
		return converted;
	}

	void clear()
	{
		cache.clear();
		cachedIconCount = -1;
	}

	/**
	 * Converts a palette-indexed sprite to ARGB. Palette entry 0 is the sprite's
	 * transparent colour, so those pixels are left fully transparent.
	 */
	private static BufferedImage toBufferedImage(IndexedSprite sprite)
	{
		if (sprite == null)
		{
			return null;
		}

		byte[] pixels = sprite.getPixels();
		int[] palette = sprite.getPalette();
		int width = sprite.getWidth();
		int height = sprite.getHeight();

		if (pixels == null || palette == null || width <= 0 || height <= 0
			|| pixels.length < width * height)
		{
			return null;
		}

		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int paletteIndex = pixels[y * width + x] & 0xFF;
				if (paletteIndex == 0 || paletteIndex >= palette.length)
				{
					continue;
				}
				image.setRGB(x, y, 0xFF000000 | palette[paletteIndex]);
			}
		}
		return image;
	}
}

package com.chatfade;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;

/**
 * The plugin's own message filtering, independent of RuneLite's Chat Filter plugin.
 *
 * <p>Holds a list of plain text fragments and a list of regular expressions. Matching is
 * done against a normalised form of the message — colour markup of both syntaxes removed,
 * trimmed, lowercased — so a filter written in plain text still matches a message the game
 * decorated with colour.
 */
@Slf4j
class IgnoreList
{
	private List<String> fragments = new ArrayList<>();
	private List<Pattern> patterns = new ArrayList<>();

	/**
	 * Reduces a message to a comparable form: no colour markup, trimmed, lowercase.
	 * Messages are macro-expanded before they get here, so {@code <...>} is the only
	 * markup left to strip.
	 */
	static String normalize(String message)
	{
		if (message == null || message.isEmpty())
		{
			return "";
		}

		return Text.removeTags(message).trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * Rebuilds both lists from raw config values. Invalid regular expressions are logged and
	 * skipped so that one bad entry cannot take the rest of the filtering down with it.
	 *
	 * @param csv comma-separated text fragments
	 * @param regexLines newline-separated regular expressions
	 */
	void rebuild(String csv, String regexLines)
	{
		List<String> newFragments = new ArrayList<>();
		for (String entry : Text.fromCSV(csv == null ? "" : csv))
		{
			String normalized = normalize(entry);
			if (!normalized.isEmpty())
			{
				newFragments.add(normalized);
			}
		}
		fragments = newFragments;

		List<Pattern> newPatterns = new ArrayList<>();
		for (String line : (regexLines == null ? "" : regexLines).split("\n"))
		{
			String trimmed = line.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			try
			{
				newPatterns.add(Pattern.compile(trimmed, Pattern.CASE_INSENSITIVE));
			}
			catch (PatternSyntaxException ex)
			{
				log.warn("Chat Fade: ignoring invalid regex \"{}\"", trimmed, ex);
			}
		}
		patterns = newPatterns;
	}

	/** @return true if the message matches any configured fragment or pattern */
	boolean matches(String rawMessage)
	{
		if (fragments.isEmpty() && patterns.isEmpty())
		{
			return false;
		}

		String normalized = normalize(rawMessage);
		if (normalized.isEmpty())
		{
			return false;
		}

		for (String fragment : fragments)
		{
			if (normalized.contains(fragment))
			{
				return true;
			}
		}

		for (Pattern pattern : patterns)
		{
			if (pattern.matcher(normalized).find())
			{
				return true;
			}
		}

		return false;
	}

	/** @return number of usable regular expressions, i.e. excluding any that failed to compile */
	int patternCount()
	{
		return patterns.size();
	}

	/** @return number of text fragments */
	int fragmentCount()
	{
		return fragments.size();
	}
}

